     attempt_count: int


 class IngestionWorker:
     def __init__(
         self,
         *,
         queue: QueueConsumer,
         store: InMemoryIngestionStore,
         http_client: httpx.AsyncBaseTransport | None = None,
         max_attempts: int = 4,
         timeout_seconds: float = 10.0,
         max_download_bytes: int = 4_194_304,
         poison_dequeue_count: int = 5,
     ) -> None:
