             self.store.record_product(
                 ProductIngestionStatus(
                     run_id=run_id,
                     product_id=product_id,
                     outcome=result["outcome"],
                     reason_category=result["reason_category"],
                     http_status=result["http_status"],
                     source_url=source_url,
