         product_name=source.name,
         source_url=source.source_url,
         title=title,
         content=content,
         content_hash=_sha256(content),
     )


 def _split_text(
     content: str,
     *,
     max_chars: int,
     overlap_chars: int,
 ) -> list[str]:
     if max_chars <= 0:
         raise ValueError("max_chars must be positive")
     if overlap_chars < 0 or overlap_chars >= max_chars:
         raise ValueError("overlap_chars must be between zero and max_chars")

     normalized = " ".join(content.split())
     if not normalized:
         return []

     chunks: list[str] = []
     start = 0
     while start < len(normalized):
         end = min(start + max_chars, len(normalized))
         if end < len(normalized) and not normalized[end].isspace():
             boundary = normalized.rfind(" ", start, end)
             if boundary > start:
                 end = boundary

         chunk = normalized[start:end].strip()
         if chunk:
             chunks.append(chunk)
         if end >= len(normalized):
             break

         next_start = end
         if overlap_chars:
             next_start = max(start + 1, end - overlap_chars)
             if normalized[next_start].isspace():
                 while next_start < len(normalized) and normalized[next_start].isspace():
                     next_start += 1
             else:
                 previous_space = normalized.rfind(" ", start, next_start)
                 if previous_space >= start:
                     next_start = previous_space + 1
         else:
             while next_start < len(normalized) and normalized[next_start].isspace():
                 next_start += 1

         if next_start <= start:
             next_start = end
         start = next_start

     return chunks


