 def evaluate_retrieval(
     cases: Sequence[RetrievalEvaluationCase],
     *,
     top_k: int = 5,
 ) -> RetrievalEvaluationReport:
     if not cases:
         raise ValueError("at least one reviewed retrieval case is required")
     if isinstance(top_k, bool) or not isinstance(top_k, int) or not 1 <= top_k <= MAX_SEARCH_TOP:
         raise ValueError(f"top_k must be between 1 and {MAX_SEARCH_TOP}")
