class P(HTMLParser):
 def __init__(self):super().__init__();self.links=[];self.scripts=[];self.frames=[];self.anchor=None
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if tag=='a' and a.get('href'):self.anchor=[a['href'],'']
  if tag=='script' and a.get('src'):self.scripts.append(a['src'])
  if tag in ('frame','iframe') and a.get('src'):self.frames.append(a['src'])
 def handle_data(self,data):
  if self.anchor is not None:self.anchor[1]+=data.strip()+' '
 def handle_endtag(self,tag):
  if tag=='a' and self.anchor is not None:self.links.append(self.anchor);self.anchor=None
for url in urls:
 if not validate_source_url(url):continue
 try:
  with httpx.Client(timeout=15,follow_redirects=False,headers={'User-Agent':'ProductSupportSourceReview/1.0'}) as c:
   with c.stream('GET',url) as r:
    data=bytearray()
    for chunk in r.iter_bytes():
     data.extend(chunk)
     if len(data)>2000000:break
    if r.status_code==200 and len(data)<=2000000:
     p=P();p.feed(bytes(data).decode('utf8','replace'))
     print(json.dumps({'url':url,'status':r.status_code,'links':p.links[:35],'frames':p.frames,'scripts':p.scripts[:8]}))
    else:print(json.dumps({'url':url,'status':r.status_code,'size_limit':len(data)>2000000}))
    if r.status_code==429 or r.status_code>=500:break
 except httpx.HTTPError as e: print(json.dumps({'url':url,'error':type(e).__name__}))
 time.sleep(1)
